<?php
namespace App\Http\Controllers;
use App\Models\ConfiguracaoEmissor; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; use Illuminate\Support\Carbon; use Illuminate\Validation\ValidationException;
class ConfiguracaoEmissorController extends Controller {
 public function show(): JsonResponse { $config=ConfiguracaoEmissor::current(); $data=$config->makeHidden(['certificado_base64','certificado_senha'])->toArray(); $data['certificado_configurado']=filled($config->certificado_base64); return response()->json($data); }
 public function update(Request $request): JsonResponse { $request->merge(['cnpj'=>preg_replace('/\D+/', '', (string)$request->input('cnpj','')), 'cep'=>preg_replace('/\D+/', '', (string)$request->input('cep','')), 'codigo_municipio_ibge'=>preg_replace('/\D+/', '', (string)$request->input('codigo_municipio_ibge','')), 'cfop_padrao'=>preg_replace('/\D+/', '', (string)$request->input('cfop_padrao','')), 'csosn_padrao'=>preg_replace('/\D+/', '', (string)$request->input('csosn_padrao',''))]); $data=$request->validate(['razao_social'=>['nullable','string','max:120'],'cnpj'=>['nullable','digits:14'],'inscricao_estadual'=>['nullable','string','max:14'],'crt'=>['required','integer','between:1,4'],'cep'=>['nullable','digits:8'],'logradouro'=>['nullable','string','max:120'],'numero'=>['nullable','string','max:20'],'bairro'=>['nullable','string','max:60'],'municipio'=>['nullable','string','max:60'],'codigo_municipio_ibge'=>['nullable','digits:7'],'uf'=>['nullable','size:2'],'ambiente'=>['required','in:1,2'],'serie_padrao'=>['required','integer','min:1','max:999'],'cfop_padrao'=>['required','digits:4'],'csosn_padrao'=>['nullable','digits:4'],'certificado_senha'=>['nullable','string','max:200'],'certificado'=>['nullable','file','mimes:pfx,p12','max:5120']], ['cnpj.digits'=>'Informe um CNPJ válido com 14 números.','cep.digits'=>'Informe um CEP válido com 8 números.','codigo_municipio_ibge.digits'=>'Informe um código IBGE com 7 números.','cfop_padrao.digits'=>'Informe um CFOP com 4 números.','csosn_padrao.digits'=>'Informe um CSOSN com 4 números.']); $config=ConfiguracaoEmissor::current(); unset($data['certificado']); if($request->hasFile('certificado')) { $file=$request->file('certificado'); $password=(string)($data['certificado_senha']??''); if($password==='') throw ValidationException::withMessages(['certificado_senha'=>'Informe a senha do certificado A1.']); $contents=file_get_contents($file->getRealPath()); $certs=[]; if(!openssl_pkcs12_read($contents,$certs,$password)||empty($certs['cert'])) throw ValidationException::withMessages(['certificado'=>'O certificado A1 não é válido ou a senha está incorreta.']); $parsed=openssl_x509_parse($certs['cert']); if(!is_array($parsed)||empty($parsed['validTo_time_t'])) throw ValidationException::withMessages(['certificado'=>'Não foi possível ler a validade do certificado A1.']); if((int)$parsed['validTo_time_t'] < now()->timestamp) throw ValidationException::withMessages(['certificado'=>'O certificado A1 está vencido. Envie um certificado dentro da validade.']); $data['certificado_base64']=base64_encode($contents); $data['certificado_validade']=Carbon::createFromTimestamp($parsed['validTo_time_t']); } if(array_key_exists('certificado_senha',$data)&&$data['certificado_senha']==='') unset($data['certificado_senha']); $config->fill($data)->save(); return $this->show(); }
}
